    q("Under the Clifford Constitution, elected members represented", ["all the provinces of Nigeria", "Lagos and Calabar", "the northern emirates", "the whole of West Africa"], 1, "Only Lagos and Calabar, and only men with a property qualification. The rest of the country was represented by officials and nominees."),
    q("The Richards Constitution of 1946 is remembered chiefly for", ["introducing the elective principle", "creating the regions", "creating the office of Prime Minister", "creating the Federal Capital Territory"], 1, "It divided the country into north, west and east, with the Cameroons attached to the east — the beginning of regionalism, which shaped Nigerian politics for the next twenty years."),
    q("Nigerians first held ministerial office with responsibility for departments under the", ["Clifford Constitution", "Richards Constitution", "Macpherson Constitution", "Republican Constitution"], 2, "Macpherson, 1951, created a Council of Ministers with Nigerian members holding portfolios. Under Clifford and Richards the executive remained the Governor and his officials."),
    q("Nigeria became a true federation with a federal Prime Minister and regional premiers under the", ["Richards Constitution of 1946", "Macpherson Constitution of 1951", "Lyttleton Constitution of 1954", "Independence Constitution of 1960"], 2, "Lyttleton, 1954, established the federation of three regions and the Federal Territory of Lagos, with a federal Prime Minister and regional premiers."),
    q("The constitution that made Lagos a Federal Territory was the", ["Richards Constitution", "Macpherson Constitution", "Lyttleton Constitution", "1979 Constitution"], 2, "Lyttleton, 1954. Lagos was separated from the Western Region so that the federal capital would not belong to any region."),
    q("At independence in 1960, Nigeria adopted", ["a presidential system", "the Westminster parliamentary system", "a one-party system", "a confederal system"], 1, "The Westminster model: a Prime Minister drawn from Parliament, a Cabinet of ministers who were also legislators, and the Queen represented by a Governor-General."),
